def test_m14_source_bound_hashes_are_current():
    for receipt_name in ("m14_01_source_validation_receipt_20260911.json", "m14_01_review_receipt_20260911.json"):
        receipt = json.loads((REPORTS / receipt_name).read_text(encoding="utf-8"))
        for name, expected in receipt.get("bound_hashes", {}).items():
            if "/" in name or "\\" in name:
                assert sha256(ROOT / name) == expected, f"{receipt_name}:{name}"

def test_m6_acceptance_dates_are_real_published_days():
    import duckdb

    m6 = load("reports/upgrade_m6/M6_START_RECEIPT.json")
    with duckdb.connect(str(ROOT / "data/database/market_research.duckdb")) as con:
        published = {
            str(row[0])
            for row in con.execute(
                "select trade_date from publication_heads where publication_id is not null"
            ).fetchall()
        }
    assert len(m6["acceptance_dates"]) == 2
    assert set(m6["acceptance_dates"]) <= published
